36	  const s = raw.trim();
37	  if (s.length <= NAME_MAX) return s;
38	  const cut = s.slice(0, NAME_MAX);
39	  const lastSpace = cut.lastIndexOf(" ");
40	  return (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trimEnd();
41	}
