52	// Sanitised JSON Schema for Anthropic's output_config.format (strips min/max keywords
53	// that would 400 — real bounds re-enforced by RerankSchema.parse after the call).
54	export const rerankJsonSchema = forStructuredOutput(
55	  z.toJSONSchema(z.object({ picks: z.array(PickShape).length(3) })),
56	) as Record<string, unknown>;
57	
58	/** The most looks a daily drop ever shows. */
59	export const MAX_PICKS = 3;
60	
61	// The PARSE shape — same fields, plus the name repair.
62	//
63	// `.min(1)`, NOT `.length(3)`. The count is never enforced ON the model —
64	// `forStructuredOutput` strips minItems/maxItems because the API 400s on them —
65	// so an exact-3 rule existed only as a post-hoc throw, and a closet with fewer
66	// than three viable combos failed the ENTIRE generation as "Couldn't reach the
67	// stylist". That is a lie: the stylist answered, with everything the wardrobe
68	// could give. It bites hardest right after onboarding's "capture your first
69	// five", which is the magic moment. Repair, don't reject — the same stance as
70	// `clampName`. An empty array is still an error; there is nothing to show.
71	export const RerankSchema = z.object({
72	  picks: z.array(PickShape.extend({ name: z.string().min(1).transform(clampName) })).min(1),
73	});
74	export type RerankResult = z.infer<typeof RerankSchema>;
75	
76	/**
77	 * The variety instruction.
78	 *
79	 * "Pick the best 3" alone produces three versions of one outfit: the model is
80	 * optimising a single notion of "best", and the candidates handed to it are
81	 * ranked, so the top of the list is naturally near-identical. Asking for the
82	 * best 3 without asking for three DIFFERENT ones gets exactly what it asks for.
83	 */
84	export const RERANK_VARIETY_RULE =
85	  "The three must be genuinely different outfits, not variations of one: no two may share the same top, and no two may share the same bottom. If the candidates cannot give you three that differ, prefer variety over a marginally higher-scoring repeat.";
86	
87	type Pick = { combo_index: number; name: string; why: string };
88	
89	/**
90	 * Drop picks that reuse a combo the model already chose.
91	 *
92	 * The schema checks the array LENGTH, never that the indices differ, so a model
93	 * returning [4, 4, 7] rendered the same outfit twice. Repair rather than reject
94	 * — the same stance as `clampName` above: a duplicated index should cost the
95	 * user one look, not the whole generation.
96	 *
97	 * Returning fewer than three is fine and deliberate: the daily drop already
98	 * tolerates a variable count (`saveDailyLooks` is delete-then-insert for exactly
99	 * this reason), and two real looks beat three where two are the same.
100	 */
101	export function dedupePicks(picks: Pick[], comboCount?: number): Pick[] {
102	  const seen = new Set<number>();
103	  return picks.filter((p) => {
104	    // An index outside the shortlist used to fall back to the FIRST combo, so
105	    // two bad indices rendered the same outfit twice — duplicates that survive
106	    // de-duplication because the indices themselves differ. Drop them instead.
107	    if (comboCount != null && (p.combo_index < 0 || p.combo_index >= comboCount)) return false;
108	    if (seen.has(p.combo_index)) return false;
109	    seen.add(p.combo_index);
110	    return true;
111	  });
112	}
113	
114	/**
115	 * Everything that stands between the model's answer and the screen: drop
116	 * repeats and out-of-range indices, then cap at MAX_PICKS. The cap lives here
117	 * rather than in the schema so an over-eager model costs the user nothing.
118	 */
119	export function finalisePicks(picks: Pick[], comboCount?: number, want = MAX_PICKS): Pick[] {
120	  return dedupePicks(picks, comboCount).slice(0, Math.max(1, want));
121	}
