131	   * day where a look has already been WORN asks for fewer, because the worn one
132	   * is pinned and still counts toward the day's three. "Today's Looks" is a set
133	   * of three — the index tabs are 01/02/03 and a fourth does not fit at 390px.
134	   */
135	  want?: number;
136	}): Promise<RerankResult> {
137	  const want = Math.max(1, Math.min(args.want ?? MAX_PICKS, MAX_PICKS));
138	  const prompt = `You are a personal stylist. The user's aesthetic is ${
139	    args.aesthetic.join(", ") || "understated, modern menswear"
140	  }. Occasion: ${args.occasion}. Weather: ${args.weatherLabel}, ${args.tempC}°C.
141	Here are candidate outfits (already filtered and scored), one per line:
142	${describeCombos(args.combos)}
143	
144	Pick the best ${want}. ${RERANK_VARIETY_RULE}
145	
146	For each return: its combo_index; a short evocative NAME (≤4 words and at most ${NAME_MAX} characters, e.g. "The Off-Duty Camel"); and ONE warm, specific sentence ("why") that references the colours/pieces (e.g. "the camel knit warms the grey trousers and picks up the loafers"). Return exactly ${want} pick${want === 1 ? "" : "s"}, each with a DIFFERENT combo_index.`;
